import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-seq0/frozen/seen/play/users/u089/system/state/hermes/state.db'
c=sqlite3.connect(p)
msgs=c.execute("select id,content from messages where session_id='64c8ef85-8815-4edc-9a8b-d6900b6f2b18' and role='user' order by id").fetchall()
for mid,text in msgs:
 if not text or 'Demo pair' not in text: continue
 print('\nMSG',mid)
 blocks=re.split(r'(?=Demo pair \d+ input)',text)
 for b in blocks:
  m=re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):',b)
  if not m: continue
  n,h,w=map(int,m.groups())
  parts=re.split(rf'Demo pair {n} output \(\d+x\d+\):',b)
  def grid(part):
   rows=[]
   for line in part.strip().splitlines():
    toks=line.strip().split()
    if len(toks)==w and all(t.isdigit() for t in toks): rows.append(list(map(int,toks)))
   return rows
  inp=grid(parts[0].split(':',1)[1]) if len(parts)>0 else []
  out=grid(parts[1]) if len(parts)>1 else []
  print('demo',n,'dims',h,w,'parsed',len(inp),len(out))
  if out:
   print('output top row',out[0]); print('output first col',[r[0] for r in out]);
  if inp:
   tracks={}
   for r,row in enumerate(inp):
    for col,v in enumerate(row):
