import sqlite3,re,collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-seq0/frozen/seen/play/users/u089/system/state/hermes/state.db'; c=sqlite3.connect(p)
rows=c.execute("select id,content from messages where session_id=? and role='user' order by id",('64c8ef85-8815-4edc-9a8b-d6900b6f2b18',)).fetchall()
for mid,s in rows:
 for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)\nDemo pair \1 output \((\d+)x(\d+)\):\n(.*?)(?=\n\nSame instance|\Z)',s,re.S):
  n=int(m.group(1));
  def parse(t): return [[int(x) for x in line.split()] for line in t.splitlines() if line.strip()]
  I,O=parse(m.group(4)),parse(m.group(7)); h,w=len(I),len(I[0]);
  # output invariant by d=c-r motif if so
  vals={}
  ok=True
  for r in range(len(O)):
   for cc in range(len(O[0])):
    d=(cc-r)%50
    if d in vals and vals[d]!=O[r][cc]:ok=False
    vals[d]=O[r][cc]
  # derive simplest period p for O(r,c)=M[(c-r)%p]
  p0=None
  for p1 in range(1,30):
   mm={}; good=True
   for r in range(len(O)):
    for cc in range(len(O[0])):
     q=(cc-r)%p1
     if q in mm and mm[q]!=O[r][cc]: good=False
     mm[q]=O[r][cc]
   if good: p0=p1; motif=[mm[i] for i in range(p1)];break
  # input d composition counts and coordinate spans
  by=collections.defaultdict(list)
  for r in range(h):
   for cc in range(w):
    if I[r][cc]:by[I[r][cc]].append((cc-r,r,cc))
  print(f'D{n} {h}x{w} period d={p0} motif={motif if p0 else None}; input colors:')
  for col,pts in sorted(by.items()):
   ds=sorted(set(x[0] for x in pts)); rows0=sorted(set(x[1] for x in pts));
   print(' ',col,'n',len(pts),'d',ds,'r range', (min(rows0),max(rows0)))
